<?php
require_once __DIR__.'/../../includes/accounting_ui.php';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');try{$stats=$ac->dashboard($from,$to);}catch(InvalidArgumentException $e){$error=$e->getMessage();$from=date('Y-m-01');$to=date('Y-m-d');$stats=$ac->dashboard($from,$to);}$today=$ac->dashboard(date('Y-m-d'),date('Y-m-d'));$month=$ac->dashboard(date('Y-m-01'),date('Y-m-d'));$check=$ac->reconcile();ob_start();
?>
<form class="d-flex flex-wrap gap-2 mb-3"><?php acInput('from','From',$from,'date');acInput('to','To',$to,'date'); ?><button class="btn btn-outline-primary align-self-end mb-2">Update range</button></form>
<div class="ac-stats mb-4"><?php foreach(['billed'=>'Issued bills (range)','collected'=>'Confirmed cash received (range)','outstanding'=>'Account outstanding (all dates)','advances'=>'Available advances (liability)','income'=>'Accrual income (range)','expense'=>'Accrual expenses (range)','net'=>'Surplus / deficit (range)','refunds'=>'Refunds (range)'] as $key=>$label): ?><div class="ac-stat"><small><?= $label ?></small><strong><?= acMoney($stats[$key]) ?></strong></div><?php endforeach; ?><div class="ac-stat"><small>Today's collection</small><strong><?= acMoney($today['collected']) ?></strong></div><div class="ac-stat"><small>This month's collection</small><strong><?= acMoney($month['collected']) ?></strong></div></div>
<div class="alert <?= $check['ok']?'alert-success':'alert-danger' ?>">Receivable and advance reconciliation: <?= $check['ok']?'balanced':'difference found — review reports before posting' ?>. <a href="<?= acUrl('reports',['type'=>'reconciliation']) ?>">Review control accounts</a></div>
<div class="row"><div class="col-lg-6"><div class="card card-body mb-3"><h4>Monthly confirmed collections</h4><?php $months=$ac->rows("SELECT SUBSTR(payment_date,1,7) month,SUM(amount_minor) amount FROM ac_payments WHERE school_id=? AND status='posted' AND payment_date>=? AND payment_date<=? GROUP BY SUBSTR(payment_date,1,7) ORDER BY month",[$school,$from,$to]);$maximum=max([1,...array_map(fn($r)=>(int)$r['amount'],$months)]); ?><div class="ac-chart"><?php foreach($months as $r): ?><div style="height:<?= (int)$r['amount']/$maximum*100 ?>%" title="<?= sanitize($r['month'].' '.acMoney((int)$r['amount'])) ?>"><b><?= acMoney((int)$r['amount']) ?></b><span><?= sanitize($r['month']) ?></span></div><?php endforeach; ?></div><?php if(!$months): ?><p>No posted collections in this range.</p><?php endif; ?></div></div><div class="col-lg-6"><div class="card card-body mb-3"><h4>Collection by payment method</h4><?php foreach($ac->rows("SELECT m.name,SUM(p.amount_minor) amount FROM ac_payments p JOIN ac_methods m ON m.id=p.method_id WHERE p.school_id=? AND p.status='posted' AND p.payment_date>=? AND p.payment_date<=? GROUP BY m.id,m.name ORDER BY amount DESC",[$school,$from,$to]) as $r): ?><p><?= sanitize($r['name']) ?> <strong><?= acMoney((int)$r['amount']) ?></strong></p><?php endforeach; ?></div></div></div>
<div class="card card-body table-responsive"><h4>Recent payments</h4><table class="table"><thead><tr><th>Receipt</th><th>Customer</th><th>Date</th><th>Received</th></tr></thead><tbody><?php foreach($ac->rows("SELECT * FROM ac_payments WHERE school_id=? AND status='posted' ORDER BY id DESC LIMIT 10",[$school]) as $r): ?><tr><td><a href="<?= acUrl('receipt',['id'=>$r['id']]) ?>"><?= sanitize($r['number']) ?></a></td><td><?= sanitize($r['customer_name']) ?></td><td><?= sanitize(schoolDateLabel($r['payment_date'],'both','ymd')) ?></td><td><?= acMoney((int)$r['amount_minor']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php acRender('Accounting overview',ob_get_clean());
